def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_prev, opp_prev = history[-1]

    opp_def = 0
    my_def = 0
    last_my_D = -100

    for i in range(n):
        s, o = history[i]
        if o == 'D':
            opp_def += 1
        if s == 'D':
            my_def += 1
            last_my_D = i

    opp_D_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_D_streak += 1
        else:
            break

    unprovoked = 0
    forgiven = 0
    punished = 0

    for i in range(1, n):
        prev_s = history[i - 1][0]
        cur_o = history[i][1]
        if prev_s == 'D':
            if cur_o == 'C':
                forgiven += 1
            else:
                punished += 1
        else:
            if cur_o == 'D':
                unprovoked += 1

    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0

    recent_opp_def = 0
    recent_unprovoked = 0
    recent_forgiven = 0
    recent_punished = 0

    for i in range(recent_start, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    for i in range(recent_start + 1, n):
        prev_s = history[i - 1][0]
        cur_o = history[i][1]
        if prev_s == 'D':
            if cur_o == 'C':
                recent_forgiven += 1
            else:
                recent_punished += 1
        else:
            if cur_o == 'D':
                recent_unprovoked += 1

    coop_rate = (n - opp_def) / float(n)

    if n >= 98:
        return 'D'

    hostile = False

    if opp_D_streak >= 3:
        hostile = True
    elif unprovoked >= 3 and recent_unprovoked >= 2:
        hostile = True
    elif coop_rate < 0.45 and opp_def >= 3 and unprovoked >= 2:
        hostile = True
