        hostile = True
    elif opp_def >= 5 and opp_def * 2 > n and forgiven < 2 and punished < 2:
        hostile = True

    if hostile:
        return 'D'

    exploitable = False

    if forgiven >= 2 and punished == 0 and unprovoked == 0 and recent_opp_def == 0:
        exploitable = True
    elif forgiven >= 5 and punished <= 1 and unprovoked <= 2 and recent_opp_def == 0 and recent_punished == 0 and recent_unprovoked == 0:
        exploitable = True
    elif opp_def == 0 and forgiven >= 1 and punished == 0 and unprovoked == 0:
        exploitable = True
    elif n >= 70 and coop_rate > 0.85 and forgiven >= 3 and punished <= 1 and recent_opp_def <= 1 and recent_punished == 0 and recent_unprovoked <= 1:
        exploitable = True

    if exploitable:
        if n >= 95:
            return 'D'

        if opp_prev == 'D':
            if opp_D_streak >= 2 or recent_opp_def >= 3:
                return 'D'
            return 'C'

        if my_prev == 'D':
            if n >= 92 and opp_def == 0:
                return 'D'
            if n >= 90 and forgiven >= 20 and recent_opp_def == 0:
                return 'D'
            return 'C'

        interval = 4
        if forgiven >= 2 and n >= 12:
            interval = 3
        if forgiven >= 20 and n >= 65:
            interval = 2
        if n >= 90:
            interval = 1

        if my_def == 0:
            return 'D'

        if n - last_my_D >= interval:
            if n < 70 and my_def * 2 >= n:
                return 'C'
            return 'D'

        return 'C'

    if my_def == 0 and n >= 8 and n <= 25 and recent_opp_def == 0 and unprovoked <= 2 and coop_rate > 0.65:
        if n == 8 or n == 14 or n == 20:
            return 'D'

    if opp_prev == 'D':
        if opp_D_streak >= 2:
            return 'D'
